import sys import syslog
# 초기 클래스.
class Logger(object):
def __init__(self, file):
self.file = file
def log(self, message):
self.file.write(message + ‘n’) self.file.flush()
# 메시지를 다른 곳으로 보내는 두 개의 추가 클래스.
class SocketLogger(Logger):
def __init__(self, sock):
self.sock = sock
def log(self, message):
self.sock.sendall((message + ‘n’).encode(‘ascii’))
class SyslogLogger(Logger):
def __init__(self, priority):
self.priority = priority
def log(self, message):
syslog.syslog(self.priority, message)



# 새로운 디자인 방향: 메시지 필터링.
class FilteredLogger(Logger):
def __init__(self, pattern, file):
self.pattern = pattern super().__init__(file)
def log(self, message):
if self.pattern in message:
super().log(message)
# 작동합니다.
f = FilteredLogger(‘Error’, sys.stdout) f.log(‘Ignored: this is not important’) f.log(‘Error: but you want to see this’)


Error: but you want to see this




